// Pseudo: acquire per-key lock, fetch fresh data, set both caches
function getFeed(key) {
  if (Redis.get(key)) return Redis.get(key)
  if (Memcache.add(key + ':lock', 1, 1)) {
    const fresh = loadFromDB(key)
    Redis.set(key, fresh, 300)
    Memcache.set(key, fresh, 300)
    Memcache.delete(key + ':lock')
    return fresh
  } else {
    // wait and retry
  }
}
```

